export enum ClockMode {
  AUTO = 'AUTO',
  MANUAL = 'MANUAL',
}

export enum ClockSkin {
  CLASSIC = 'CLASSIC',
  CYBER = 'CYBER',
}

import React from 'react';
import { ClockMode, ClockSkin } from '../types';

interface ControlsProps {
  mode: ClockMode;
  setMode: (mode: ClockMode) => void;
  skin: ClockSkin;
  setSkin: (skin: ClockSkin) => void;
  manualTimeOffset: number;
  setManualTimeOffset: (offset: number) => void;
  onClose: () => void;
}

const Controls: React.FC<ControlsProps> = ({ 
  mode, 
  setMode, 
  skin,
  setSkin,
  manualTimeOffset, 
  setManualTimeOffset,
  onClose
}) => {
  const handleModeChange = (newMode: ClockMode) => {
    setMode(newMode);
    if (newMode === ClockMode.AUTO) {
      setManualTimeOffset(0);
    }
  };

  const adjustTime = (seconds: number) => {
    setMode(ClockMode.MANUAL);
    setManualTimeOffset(manualTimeOffset + seconds * 1000);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-md p-4">
      <div className="bg-gray-900 border border-gray-700 rounded-xl p-6 w-full max-w-md shadow-2xl relative">
        <button 
          onClick={onClose}
          className="absolute top-4 right-4 text-gray-400 hover:text-white"
        >
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
        </button>

        <h2 className="text-xl font-bold text-[#ff5500] mb-6 font-mono tracking-wider">CLOCK SETTINGS</h2>

        <div className="space-y-6">
          {/* Mode Selection */}
          <div>
            <label className="text-gray-400 text-xs mb-2 block uppercase tracking-widest">Time Mode</label>
            <div className="flex bg-gray-800 p-1 rounded-lg">
              <button
                onClick={() => handleModeChange(ClockMode.AUTO)}
                className={`flex-1 py-2 px-4 rounded-md text-sm font-bold transition-colors ${
                  mode === ClockMode.AUTO 
                    ? 'bg-[#ff5500] text-black shadow-lg' 
                    : 'text-gray-400 hover:text-white'
                }`}
              >
                AUTO
              </button>
              <button
                onClick={() => handleModeChange(ClockMode.MANUAL)}
                className={`flex-1 py-2 px-4 rounded-md text-sm font-bold transition-colors ${
                  mode === ClockMode.MANUAL 
                    ? 'bg-[#ff5500] text-black shadow-lg' 
                    : 'text-gray-400 hover:text-white'
                }`}
              >
                MANUAL
              </button>
            </div>
          </div>

          {/* Skin Selection */}
          <div>
            <label className="text-gray-400 text-xs mb-2 block uppercase tracking-widest">Appearance</label>
            <div className="flex bg-gray-800 p-1 rounded-lg">
              <button
                onClick={() => setSkin(ClockSkin.CLASSIC)}
                className={`flex-1 py-2 px-4 rounded-md text-sm font-bold transition-colors ${
                  skin === ClockSkin.CLASSIC
                    ? 'bg-[#ff5500] text-black shadow-lg' 
                    : 'text-gray-400 hover:text-white'
                }`}
              >
                CLASSIC
              </button>
              <button
                onClick={() => setSkin(ClockSkin.CYBER)}
                className={`flex-1 py-2 px-4 rounded-md text-sm font-bold transition-colors ${
                  skin === ClockSkin.CYBER 
                    ? 'bg-cyan-500 text-black shadow-[0_0_10px_cyan]' 
                    : 'text-gray-400 hover:text-cyan-400'
                }`}
              >
                CYBER
              </button>
            </div>
          </div>

          {/* Manual Controls */}
          <div className={`transition-opacity duration-300 ${mode === ClockMode.MANUAL ? 'opacity-100' : 'opacity-40 pointer-events-none'}`}>
            <p className="text-gray-400 text-xs mb-3 text-center uppercase tracking-widest">Adjust Current Time</p>
            <div className="grid grid-cols-3 gap-2">
              <div className="flex flex-col gap-2">
                <button onClick={() => adjustTime(3600)} className="bg-gray-800 hover:bg-gray-700 text-[#ff5500] py-2 rounded border border-gray-700">+1 Hr</button>
                <button onClick={() => adjustTime(-3600)} className="bg-gray-800 hover:bg-gray-700 text-[#ff5500] py-2 rounded border border-gray-700">-1 Hr</button>
              </div>
              <div className="flex flex-col gap-2">
                <button onClick={() => adjustTime(60)} className="bg-gray-800 hover:bg-gray-700 text-[#ff5500] py-2 rounded border border-gray-700">+1 Min</button>
                <button onClick={() => adjustTime(-60)} className="bg-gray-800 hover:bg-gray-700 text-[#ff5500] py-2 rounded border border-gray-700">-1 Min</button>
              </div>
              <div className="flex flex-col gap-2">
                <button onClick={() => adjustTime(1)} className="bg-gray-800 hover:bg-gray-700 text-[#ff5500] py-2 rounded border border-gray-700">+1 Sec</button>
                <button onClick={() => adjustTime(-1)} className="bg-gray-800 hover:bg-gray-700 text-[#ff5500] py-2 rounded border border-gray-700">-1 Sec</button>
              </div>
            </div>
          </div>

          {/* Info */}
          <div className="text-center pt-4 border-t border-gray-800">
             <p className="text-gray-500 text-xs">
               {mode === ClockMode.AUTO ? "Syncing with Internet Time via System" : "Manual Time Offset Active"}
             </p>
          </div>
        </div>
      </div>
    </div>
  );
};

