              >
                AUTO
              </button>
              <button
                onClick={() => handleModeChange(ClockMode.MANUAL)}
                className={`flex-1 py-2 px-4 rounded-md text-sm font-bold transition-colors ${
                  mode === ClockMode.MANUAL 
                    ? 'bg-[#ff5500] text-black shadow-lg' 
                    : 'text-gray-400 hover:text-white'
