      {/* UI Controls (Floating Action Buttons) */}
      <div 
        className={`absolute bottom-8 right-8 z-30 flex gap-4 transition-opacity duration-300 ${uiVisible ? 'opacity-100' : 'opacity-0 pointer-events-none'}`}
