<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>Retro Nixie Clock</title>
    <link rel="stylesheet" href="style.css">
    <link rel="icon" type="image/svg+xml" href="favicon.svg">
    <style>
        body {
            background-color: #222;
            color: #ddd;
            font-family: monospace;
            display: flex;
            justify-content: center;
            align-items: center;
            height: 100vh;
            margin: 0;
            overflow: hidden;
        }

        #app {
            text-align: center;
        }
    </style>
    <script src="https://unpkg.com/@babel/standalone/babel.min.js"></script>
    <script crossorigin src="https://unpkg.com/react@18/umd/react.production.min.js"></script>
    <script crossorigin src="https://unpkg.com/react-dom@18/umd/react-dom.production.min.js"></script>
</head>
<body>
    <div id="app">
        <!-- React App will render here -->
    </div>
    <script type="text/babel">
    // Define the TypeScript code directly within this script block.  Imports are removed.
    // types.ts
    enum Segment {
        A = 1 << 0,
        B = 1 << 1,
        C = 1 << 2,
        D = 1 << 3,
        E = 1 << 4,
        F = 1 << 5,
        G = 1 << 6,
        DP = 1 << 7,
    }

    interface TubeProps {
        digit: number;
        segments: Segment;
        active: boolean;
        theme: string;
    }

    interface NeonSeparatorProps {
        active: boolean;
        theme: string;
    }

    interface ControlProps {
        onHourUp: () => void;
        onHourDown: () => void;
        onMinuteUp: () => void;
        onMinuteDown: () => void;
        onThemeChange: () => void;
        theme: string;
    }
    // NixieTube.tsx
    function NixieTube(props: TubeProps) {
        const { digit, segments, active, theme } = props;
        const segmentClass = (segment: Segment) => {
            return (segments & segment) ? 'on' : 'off';
        };

        const themeClass = theme === 'dark' ? 'dark' : 'light';
        const activeClass = active ? 'active' : '';

        return (
            <div className={`nixie-tube ${themeClass} ${activeClass}`}>
                <div className={`segment a ${segmentClass(Segment.A)}`}></div>
                <div className={`segment b ${segmentClass(Segment.B)}`}></div>
                <div className={`segment c ${segmentClass(Segment.C)}`}></div>
                <div className={`segment d ${segmentClass(Segment.D)}`}></div>
                <div className={`segment e ${segmentClass(Segment.E)}`}></div>
                <div className={`segment f ${segmentClass(Segment.F)}`}></div>
                <div className={`segment g ${segmentClass(Segment.G)}`}></div>
                <div className={`segment dp ${segmentClass(Segment.DP)}`}></div>
                <div className="digit">{digit}</div>
            </div>
        );
    }
    // NeonSeparator.tsx
    function NeonSeparator(props: NeonSeparatorProps) {
        const { active, theme } = props;
        const themeClass = theme === 'dark' ? 'dark' : 'light';
        const activeClass = active ? 'active' : '';

        return (
            <div className={`neon-separator ${themeClass} ${activeClass}`}>
                <div className="dot"></div>
                <div className="dot"></div>
            </div>
        );

**Adapting for Legacy Browsers**

I'm now focusing on ensuring the application is compatible with older browsers like the iPad 2. Since this uses React 18 and doesn't have a `fetch` dependency, it should run, but I'll add the `"env"` Babel preset to target older browser versions to ensure ES5 compatibility. I may need to use polyfills, but I am assuming that the core issue is the scripts not loading.

