              </button>
            </div>
          </div>

          {/* Precision Selection */}
          <div>
            <label className="text-gray-400 text-xs mb-2 block uppercase tracking-widest">Precision</label>
            <div className="flex bg-gray-800 p-1 rounded-lg">
              <button
                onClick={() => setPrecision(ClockPrecision.MINUTES)}
                className={`flex-1 py-2 px-4 rounded-md text-sm font-bold transition-colors ${getSegmentButtonClass(precision === ClockPrecision.MINUTES)}`}
              >
                HH:MM
              </button>
              <button
                onClick={() => setPrecision(ClockPrecision.SECONDS)}
                className={`flex-1 py-2 px-4 rounded-md text-sm font-bold transition-colors ${getSegmentButtonClass(precision === ClockPrecision.SECONDS)}`}
              >
                HH:MM:SS
              </button>
            </div>
          </div>

          {/* Manual Time Controls */}
          <div className={`transition-opacity duration-300 ${mode === ClockMode.MANUAL ? 'opacity-100' : 'opacity-40 pointer-events-none'}`}>
            <p className="text-gray-400 text-xs mb-3 text-center uppercase tracking-widest">Adjust Current Time</p>
            <div className="grid grid-cols-3 gap-2">
              <div className="flex flex-col gap-2">
                <button onClick={() => adjustTime(3600)} className={`bg-gray-800 hover:bg-gray-700 ${activeTextClass} py-2 rounded border border-gray-700`}>+1 Hr</button>
                <button onClick={() => adjustTime(-3600)} className={`bg-gray-800 hover:bg-gray-700 ${activeTextClass} py-2 rounded border border-gray-700`}>-1 Hr</button>
              </div>
              <div className="flex flex-col gap-2">
                <button onClick={() => adjustTime(60)} className={`bg-gray-800 hover:bg-gray-700 ${activeTextClass} py-2 rounded border border-gray-700`}>+1 Min</button>
                <button onClick={() => adjustTime(-60)} className={`bg-gray-800 hover:bg-gray-700 ${activeTextClass} py-2 rounded border border-gray-700`}>-1 Min</button>
              </div>
              <div className="flex flex-col gap-2">
                <button onClick={() => adjustTime(1)} className={`bg-gray-800 hover:bg-gray-700 ${activeTextClass} py-2 rounded border border-gray-700`}>+1 Sec</button>
                <button onClick={() => adjustTime(-1)} className={`bg-gray-800 hover:bg-gray-700 ${activeTextClass} py-2 rounded border border-gray-700`}>-1 Sec</button>
              </div>
            </div>
          </div>

          <hr className="border-gray-800" />

          {/* Skin Selection */}
          <div>
            <label className="text-gray-400 text-xs mb-2 block uppercase tracking-widest">Skin</label>
            <div className="flex bg-gray-800 p-1 rounded-lg">
              <button
                onClick={() => setSkin(ClockSkin.CLASSIC)}
                className={`flex-1 py-2 px-2 rounded-md text-sm font-bold transition-colors ${
                  skin === ClockSkin.CLASSIC
                    ? 'bg-[#ff5500] text-black shadow-lg' 
                    : 'text-gray-400 hover:text-white'
                }`}
              >
                CLASSIC
              </button>
               <button
                onClick={() => setSkin(ClockSkin.LIGHT)}
                className={`flex-1 py-2 px-2 rounded-md text-sm font-bold transition-colors ${
                  skin === ClockSkin.LIGHT
                    ? 'bg-[#0088ff] text-black shadow-lg' 
                    : 'text-gray-400 hover:text-white'
                }`}
              >
                LIGHT
              </button>
              <button
                onClick={() => setSkin(ClockSkin.LED)}
                className={`flex-1 py-2 px-2 rounded-md text-sm font-bold transition-colors ${
                  skin === ClockSkin.LED
                    ? 'bg-[#d600ff] text-black shadow-lg' 
                    : 'text-gray-400 hover:text-white'
                }`}
              >
                LED
              </button>
              <button
                onClick={() => setSkin(ClockSkin.CYBER)}
                className={`flex-1 py-2 px-2 rounded-md text-sm font-bold transition-colors ${
                  skin === ClockSkin.CYBER 
                    ? 'bg-cyan-500 text-black shadow-[0_0_10px_cyan]' 
                    : 'text-gray-400 hover:text-cyan-400'
                }`}
              >
                CYBER
              </button>
            </div>
          </div>

          {/* Font Selection */}
          <div>
            <label className="text-gray-400 text-xs mb-2 block uppercase tracking-widest">Digit Font</label>
            <div className="bg-gray-800 p-2 rounded-lg">
              <select 
                value={font} 
                onChange={(e) => setFont(e.target.value as ClockFont)}
                className={`w-full bg-gray-900 text-white p-2 rounded border focus:outline-none ${activeBorderClass} border-gray-700`}
              >
                <option value={ClockFont.NIXIE_ONE}>Nixie One (Thin)</option>
                <option value={ClockFont.SHARE_TECH}>Share Tech (Modern)</option>
                <option value={ClockFont.ORBITRON}>Orbitron (Sci-Fi)</option>
                <option value={ClockFont.WALLPOET}>Wallpoet (Stencil)</option>
              </select>
            </div>
          </div>

          {/* Color Mode Selection */}
          <div>
            <label className="text-gray-400 text-xs mb-2 block uppercase tracking-widest">Glow Color</label>
            <div className="flex bg-gray-800 p-1 rounded-lg mb-3">
               <button
                onClick={() => setColorMode(ClockColorMode.DEFAULT)}
                className={`flex-1 py-2 text-xs font-bold rounded transition-colors ${
                  colorMode === ClockColorMode.DEFAULT ? 'bg-white text-black' : 'text-gray-400'
                }`}
              >
                SKIN
              </button>
              <button
                onClick={() => setColorMode(ClockColorMode.FIXED)}
                className={`flex-1 py-2 text-xs font-bold rounded transition-colors ${
                  colorMode === ClockColorMode.FIXED ? 'bg-white text-black' : 'text-gray-400'
                }`}
              >
                FIXED
              </button>
              <button
                onClick={() => setColorMode(ClockColorMode.RAINBOW)}
                className={`flex-1 py-2 text-xs font-bold rounded transition-colors ${
                  colorMode === ClockColorMode.RAINBOW ? 'bg-gradient-to-r from-red-500 via-green-500 to-blue-500 text-white' : 'text-gray-400'
                }`}
              >
                RGB
              </button>
            </div>

            {/* Custom Color Picker & Presets */}
            {colorMode === ClockColorMode.FIXED && (
              <div className="flex flex-col gap-3 bg-gray-800 p-3 rounded-lg border border-gray-700">
                <div className="flex items-center gap-4">
                  <input 
                    type="color" 
                    value={customColor}
                    onChange={(e) => setCustomColor(e.target.value)}
                    className="w-10 h-10 rounded cursor-pointer bg-transparent border-0 p-0"
                  />
                  <span className="text-gray-300 font-mono text-sm">{customColor.toUpperCase()}</span>
                  <div className="flex-1"></div>
                  <div className="text-xs text-gray-500">Pick any color</div>
                </div>

                {/* Preset Swatches */}
                <div className="flex gap-2 justify-between">
                  {PRESET_COLORS.map(c => (
                    <button 
                      key={c}
                      onClick={() => setCustomColor(c)}
                      className={`w-6 h-6 rounded-full border border-gray-600 transition-transform hover:scale-110 ${customColor === c ? 'ring-2 ring-white scale-110' : ''}`}
                      style={{ backgroundColor: c }}
                      title={c}
                    />
                  ))}
                </div>
              </div>
            )}
          </div>

          {/* Info */}
          <div className="text-center pt-4 border-t border-gray-800">
             <p className="text-gray-500 text-xs">
               {mode === ClockMode.AUTO ? "Syncing with Internet Time via System" : "Manual Time Offset Active"}
             </p>
          </div>
        </div>
      </div>
    </div>
  );
};

const { useState, useEffect, useCallback, useRef } = React;

function App() {
  const [mode, setMode] = useState(ClockMode.AUTO);
  const [skin, setSkin] = useState(ClockSkin.CLASSIC);
  const [font, setFont] = useState(ClockFont.NIXIE_ONE);

  // Color configuration
  const [colorMode, setColorMode] = useState(ClockColorMode.DEFAULT);
  const [customColor, setCustomColor] = useState('#00ff00'); // Default Green for custom
  const [rainbowHue, setRainbowHue] = useState(0); // Dynamic Hue for Rainbow mode

  const [manualTimeOffset, setManualTimeOffset] = useState(0); // in milliseconds
  const [showControls, setShowControls] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);

  // Scale / Zoom factor (1 = default responsive size)
  const [zoom, setZoom] = useState(1);

  // Sound & Effects State
  const [soundEnabled, setSoundEnabled] = useState(false);
  const [glitchEnabled, setGlitchEnabled] = useState(false);

  // Precision State (Seconds vs Minutes)
  const [precision, setPrecision] = useState(ClockPrecision.SECONDS);

  // UI Visibility State (Hidden by default for simulation feel)
  const [uiVisible, setUiVisible] = useState(false);

  const audioCtxRef = useRef(null);
  const soundNodesRef = useRef(null);

  const [timeState, setTimeState] = useState({
    hours: 0,
    minutes: 0,
    seconds: 0
  });

  const [separatorOn, setSeparatorOn] = useState(true);

  // --- RAINBOW LOOP (JS-Based for Max Compatibility) ---
  useEffect(() => {
    if (colorMode !== ClockColorMode.RAINBOW) return;

    let animationFrameId;
    let currentHue = rainbowHue;

    const animate = () => {
      // Increment Hue. 0.5 per frame is roughly 30 degrees per second (12s full cycle)
      currentHue = (currentHue + 0.5) % 360;
      setRainbowHue(currentHue);
      animationFrameId = requestAnimationFrame(animate);
    };

    animate();

    return () => {
      if (animationFrameId) cancelAnimationFrame(animationFrameId);
    };
  }, [colorMode]);

  // Helper to get color for a specific position index
  // Creates a rainbow wave effect across the clock
  const getColorForIndex = (index) => {
    if (colorMode === ClockColorMode.RAINBOW) {
      // Offset the hue by 25 degrees per index to create a gradient wave
      const hue = (rainbowHue - index * 25) % 360;
      return `hsl(${Math.floor(hue)}, 100%, 75%)`;
    }
    return customColor;
  };

  // Sound Toggle Handler
  const toggleSound = useCallback(() => {
    // If we are turning it on, ensure Context is created/resumed within user gesture
    if (!soundEnabled) {
      try {
        const AudioContext = window.AudioContext || window.webkitAudioContext;
        if (!audioCtxRef.current) {
          audioCtxRef.current = new AudioContext();
        }
        if (audioCtxRef.current.state === 'suspended') {
          audioCtxRef.current.resume().catch(e => console.warn("Audio resume failed", e));
        }
      } catch (e) {
        console.error("Audio init failed", e);
      }
    }
    setSoundEnabled(prev => !prev);
  }, [soundEnabled]);

  // Glitch Toggle Handler
  const toggleGlitch = useCallback(() => {
    setGlitchEnabled(prev => !prev);
  }, []);

  // Screen Click Handler for Toggling UI
  const handleScreenClick = useCallback(() => {
    setUiVisible(prev => !prev);
  }, []);

  // Sound Effect Logic
  useEffect(() => {
    if (soundEnabled) {
      try {
        const AudioContext = window.AudioContext || window.webkitAudioContext;
        if (!audioCtxRef.current) {
          audioCtxRef.current = new AudioContext();
        }
        const ctx = audioCtxRef.current;

        // Safety resume
        if (ctx.state === 'suspended') {
          ctx.resume().catch(e => {});
        }

        // Master Gain for Effect
        const masterGain = ctx.createGain();
        // Increased volume significantly so it is audible on tablets
        masterGain.gain.value = 0.15; 
        masterGain.connect(ctx.destination);

        // Oscillator 1: Mains Hum (Sawtooth for buzz character)
        const osc1 = ctx.createOscillator();
        osc1.type = 'sawtooth';
        osc1.frequency.value = 55; // Slightly offset from 50Hz for richer sound

        // Filter 1: Lowpass 
        // Increased cutoff to 600Hz (was 120Hz). 
        // Small speakers cannot play 50Hz. They need the upper harmonics (100-500Hz) to be heard.
        const filter = ctx.createBiquadFilter();
        filter.type = 'lowpass';
        filter.frequency.value = 600; 
        filter.Q.value = 1;

        osc1.connect(filter);
        filter.connect(masterGain);
        osc1.start();

        // Oscillator 2: High frequency inverter whine
        const osc2 = ctx.createOscillator();
        osc2.type = 'sine';
        // Lowered to 8kHz (was 14kHz) to be more universally audible and less harsh, 
        // while still sounding like a capacitor whine.
        osc2.frequency.value = 8000; 

        const gain2 = ctx.createGain();
        gain2.gain.value = 0.03; // Keep the whine subtle relative to the hum

        osc2.connect(gain2);
        gain2.connect(masterGain);
        osc2.start();

        soundNodesRef.current = { oscs: [osc1, osc2], gain: masterGain };

      } catch (e) {
        console.error("Audio setup error", e);
      }
    } else {
      // Cleanup nodes
      if (soundNodesRef.current) {
        soundNodesRef.current.oscs.forEach((o) => {
          try { o.stop(); o.disconnect(); } catch(e){}
        });
        soundNodesRef.current.gain.disconnect();
        soundNodesRef.current = null;
      }

      // Suspend context to save battery
      if (audioCtxRef.current && audioCtxRef.current.state === 'running') {
        audioCtxRef.current.suspend().catch(e => {});
      }
    }

    return () => {
       // Cleanup on unmount
       if (soundNodesRef.current) {
         soundNodesRef.current.oscs.forEach((o) => {
            try { o.stop(); } catch(e){}
         });
       }
    }
  }, [soundEnabled]);

  // Main Clock Tick
  useEffect(() => {
    const updateTime = () => {
      const now = new Date();

      // If manual mode, add the offset to current system time
      const effectiveTime = mode === ClockMode.MANUAL 
        ? new Date(now.getTime() + manualTimeOffset)
        : now;

      setTimeState({
        hours: effectiveTime.getHours(),
        minutes: effectiveTime.getMinutes(),
        seconds: effectiveTime.getSeconds()
      });

      // Synchronize separator blinking: ON for first 500ms, OFF for next 500ms
      // This ensures it blinks exactly when the second changes
      setSeparatorOn(effectiveTime.getMilliseconds() < 500);
    };

    // Update immediately
    updateTime();

    // High precision timer to minimize drift and keep blinking tight
    const timerId = setInterval(updateTime, 50);

    return () => clearInterval(timerId);
  }, [mode, manualTimeOffset]);

  // Handle Fullscreen
  const toggleFullscreen = useCallback(() => {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen().catch((e) => {
        console.warn("Fullscreen error:", e);
      });
      setIsFullscreen(true);
    } else {
      if (document.exitFullscreen) {
        document.exitFullscreen();
        setIsFullscreen(false);
      }
    }
  }, []);

  // Split digits helper
  const splitDigits = (num) => {
    return [Math.floor(num / 10), num % 10];
  };

  const [h1, h2] = splitDigits(timeState.hours);
  const [m1, m2] = splitDigits(timeState.minutes);
  const [s1, s2] = splitDigits(timeState.seconds);

  // Determine global background based on skin
  let bgGradient = "";
  if (skin === ClockSkin.CLASSIC) {
    bgGradient = 'radial-gradient(circle at center, #1a0800 0%, #000000 70%)';
  } else if (skin === ClockSkin.LIGHT) {
    // Blue/Black void for blue glass look
    bgGradient = 'radial-gradient(circle at center, #001020 0%, #000510 50%, #000000 100%)';
  } else if (skin === ClockSkin.LED) {
    // Dark matte desk look
    bgGradient = 'radial-gradient(circle at center, #1a1a1a 0%, #050505 80%)';
  } else {
    bgGradient = 'radial-gradient(circle at center, #050a14 0%, #000000 70%)';
  }

  // Container Shadow styles
  const containerStyle = skin === ClockSkin.CLASSIC
    ? { boxShadow: '0 20px 50px rgba(0,0,0,0.8), inset 0 0 0 1px rgba(255,255,255,0.05)' }
    : (skin === ClockSkin.LIGHT 
        // Subtle blue ambient glow for the container group
        ? { boxShadow: '0 0 0 rgba(0,0,0,0)' } 
        : (skin === ClockSkin.LED 
            ? { boxShadow: '0 0 0 rgba(0,0,0,0)' } 
            : { boxShadow: '0 20px 50px rgba(0,0,0,0.9), inset 0 0 0 1px rgba(0,255,255,0.05), 0 0 60px rgba(0,200,255,0.05)' }));

  let containerBg = "";
  if (skin === ClockSkin.CLASSIC) {
    containerBg = "bg-black/30 border-white/5";
  } else if (skin === ClockSkin.LIGHT) {
    // Transparent/Invisible container for the floating tubes look
    containerBg = "bg-transparent border-none";
  } else if (skin === ClockSkin.LED) {
     // LED skin is self-contained with its base
     containerBg = "bg-transparent border-none";
  } else {
    containerBg = "bg-[#02060a]/50 border-cyan-500/10";
  }

  const uiBtnHoverClass = skin === ClockSkin.CYBER 
     ? 'hover:bg-cyan-500 hover:border-cyan-500 hover:shadow-cyan-500' 
     : (skin === ClockSkin.LIGHT 
        ? 'hover:bg-[#0088ff] hover:text-white hover:border-[#0088ff] hover:shadow-[#0088ff]' 
        : (skin === ClockSkin.LED ? 'hover:bg-[#d600ff] hover:text-white hover:border-[#d600ff] hover:shadow-[#d600ff]' : 'hover:bg-[#ff5500] hover:border-[#ff5500] hover:shadow-[#ff5500]'));

  return (
    <div 
      className="relative w-screen h-screen bg-[#0a0a0a] flex flex-col items-center justify-center overflow-hidden font-['Share_Tech_Mono'] cursor-pointer"
      onClick={handleScreenClick}
    >

      {/* Background Ambience */}
      <div className="absolute inset-0 transition-all duration-1000 ease-in-out pointer-events-none opacity-80" 
           style={{ background: bgGradient }}></div>

      {/* Wood/Metal Base Platform (Visual element) */}
      {/* LED Skin Base */}
      {skin === ClockSkin.LED && (
         <div className="absolute bottom-0 w-full h-1/3 bg-gradient-to-t from-[#2a1a10] via-[#3d2b22] to-transparent pointer-events-none"></div>
      )}

      {/* Standard Base */}
      {(skin !== ClockSkin.LIGHT && skin !== ClockSkin.LED) && (
        <div className="absolute bottom-0 w-full h-1/3 bg-gradient-to-t pointer-events-none from-black via-[#0f0f0f] to-transparent"></div>
      )}

      {/* Main Clock Container */}
      {/* This outer div handles responsive scaling */}
      <div className="relative z-10 flex flex-col items-center transition-transform duration-500 ease-out origin-center
          scale-[0.55] sm:scale-[0.65] md:scale-[0.75] lg:scale-[0.85] xl:scale-[1.0] 2xl:scale-[1.2]">

        {/* Inner Zoom Wrapper - Handles user manual zoom */}
        <div 
          style={{ transform: `scale(${zoom})` }} 
          className="flex flex-col items-center transition-transform duration-200 ease-out origin-center"
        >
          {/* LED Skin Wood Base Platform */}
          {skin === ClockSkin.LED && (
              <div className="absolute bottom-2 inset-x-[-20px] h-16 bg-[#3d251e] border-t-2 border-[#5d3a2e] rounded-sm shadow-[0_10px_30px_rgba(0,0,0,0.8)] z-0"></div>
          )}

          {/* The Tubes */}
          <div className={`flex items-start justify-center p-2 sm:p-4 md:p-6 lg:p-8 rounded-3xl transition-all duration-500 ${containerBg}`}
               style={containerStyle}>

            {/* Hours */}
            <div className="flex z-10">
              <NixieTube value={h1} skin={skin} font={font} colorMode={colorMode} customColor={getColorForIndex(0)} flickerEnabled={glitchEnabled} />
              <NixieTube value={h2} label="HOURS" skin={skin} font={font} colorMode={colorMode} customColor={getColorForIndex(1)} flickerEnabled={glitchEnabled} />
            </div>

            <NeonSeparator on={separatorOn} skin={skin} colorMode={colorMode} customColor={getColorForIndex(2)} flickerEnabled={glitchEnabled} />

            {/* Minutes */}
            <div className="flex z-10">
              <NixieTube value={m1} skin={skin} font={font} colorMode={colorMode} customColor={getColorForIndex(3)} flickerEnabled={glitchEnabled} />
              <NixieTube value={m2} label="MINUTES" skin={skin} font={font} colorMode={colorMode} customColor={getColorForIndex(4)} flickerEnabled={glitchEnabled} />
            </div>

            {/* Seconds (Conditional) */}
            {precision === ClockPrecision.SECONDS && (
              <>
                <NeonSeparator on={separatorOn} skin={skin} colorMode={colorMode} customColor={getColorForIndex(5)} flickerEnabled={glitchEnabled} />

                <div className="flex z-10">
                  <NixieTube value={s1} skin={skin} font={font} colorMode={colorMode} customColor={getColorForIndex(6)} flickerEnabled={glitchEnabled} />
                  <NixieTube value={s2} label="SECONDS" skin={skin} font={font} colorMode={colorMode} customColor={getColorForIndex(7)} flickerEnabled={glitchEnabled} />
                </div>
              </>
            )}

          </div>

          {/* Reflection on surface */}
          <div className={`h-16 w-full opacity-20 scale-y-[-0.5] bg-gradient-to-t from-transparent blur-xl mt-[-20px] pointer-events-none transition-colors duration-500
            ${skin === ClockSkin.CYBER ? 'to-cyan-600' : (skin === ClockSkin.LIGHT ? 'to-[#0055ff]' : (skin === ClockSkin.LED ? 'to-purple-500' : 'to-[#ff5500]'))}`}>
          </div>
        </div>
      </div>

      {/* UI Controls (Floating Action Buttons) */}
      <div 
        className={`absolute bottom-8 right-8 z-30 flex gap-4 transition-opacity duration-300 ${uiVisible ? 'opacity-100' : 'opacity-0 pointer-events-none'}`}
        onClick={(e) => e.stopPropagation()}
      >
        {/* Settings Toggle */}
        <button 
          onClick={() => setShowControls(true)}
          className={`p-3 rounded-full bg-gray-800/50 border border-gray-600 text-gray-300 hover:text-black hover:shadow-[0_0_15px] transition-all duration-300
            ${uiBtnHoverClass}`}
          title="Settings"
        >
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
        </button>

        {/* Fullscreen Toggle */}
        <button 
          onClick={toggleFullscreen}
          className="p-3 rounded-full bg-gray-800/50 border border-gray-600 text-gray-300 hover:bg-white hover:text-black hover:shadow-lg transition-all duration-300"
          title="Fullscreen"
        >
          {isFullscreen ? (
             <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
          ) : (
             <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5M4 16v4m0 0h4m-4 0l5-5m11 5l-5-5m5 5v-4m0 4h-4"></path></svg>
          )}
        </button>
      </div>

      {/* Settings Modal */}
      {showControls && (
        <Controls 
          mode={mode} 
          setMode={setMode}
          skin={skin}
          setSkin={setSkin}
          font={font}
          setFont={setFont}
          colorMode={colorMode}
          setColorMode={setColorMode}
          customColor={customColor}
          setCustomColor={setCustomColor}
          manualTimeOffset={manualTimeOffset} 
          setManualTimeOffset={setManualTimeOffset}
          zoom={zoom}
          setZoom={setZoom}
          soundEnabled={soundEnabled}
          toggleSound={toggleSound}
          glitchEnabled={glitchEnabled}
          toggleGlitch={toggleGlitch}
          precision={precision}
          setPrecision={setPrecision}
          onClose={() => setShowControls(false)}
        />
      )}
    </div>
  );
}

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

