  let innerGlowClass = isClassic ? "from-[#ff2200]/10 via-transparent to-black" : (isLight ? "from-[#0044ff]/10 via-transparent to-transparent" : "from-[#ff0033]/10 via-cyan-900/5 to-[#000510]");

  return (
