      <div className={`relative w-20 h-32 sm:w-24 sm:h-40 md:w-36 md:h-56 lg:w-44 lg:h-64 rounded-t-full rounded-b-xl overflow-hidden transition-all duration-500 ${tubeContainerClasses}`}>
