  if (colorMode === ClockColorMode.FIXED || colorMode === ClockColorMode.RAINBOW) {
    const c = customColor; 
    currentTextShadow = `0 0 5px ${c}, 0 0 10px ${c}, 0 0 20px ${c}, 0 0 40px ${c}, 0 0 70px ${c}`;
    currentColor = c; 
    currentStroke = `0.03em ${c}`;
  } else {
    if (isCyber) {
