                <div className="absolute top-0 inset-x-0 h-4 bg-[#222] border-b border-[#333] z-30 flex justify-between items-center px-1">
                    <div className="w-1.5 h-1.5 rounded-full bg-black shadow-[inset_0_0_2px_gray]"></div>
